#!/usr/bin/env bash
source "$(dirname "$0")/_common.sh"; require_execute "$@"; started=$(iso_now); stamp=$(date +%s); dump="$RESULTS/raw/backup-$stamp.dump"; log="$RESULTS/raw/backup-restore-$stamp.log"; out="$RESULTS/backup-restore-$stamp.tfproof.json"; db="telemetryforge_restore_$stamp"
set +e
{ docker compose up -d --wait timescaledb; docker compose exec -T timescaledb pg_dump -U telemetryforge -d telemetryforge -Fc >"$dump"; before=$(docker compose exec -T timescaledb psql -U telemetryforge -d telemetryforge -Atc "SELECT (SELECT count(*) FROM telemetry_events)+(SELECT count(*) FROM incidents)+(SELECT count(*) FROM routing_deliveries);"); docker compose exec -T timescaledb createdb -U telemetryforge "$db"; cat "$dump" | docker compose exec -T timescaledb pg_restore -U telemetryforge -d "$db" --no-owner; after=$(docker compose exec -T timescaledb psql -U telemetryforge -d "$db" -Atc "SELECT (SELECT count(*) FROM telemetry_events)+(SELECT count(*) FROM incidents)+(SELECT count(*) FROM routing_deliveries);"); echo BEFORE=$before AFTER=$after; [[ "$before" == "$after" ]]; docker compose exec -T timescaledb dropdb -U telemetryforge "$db"; } >"$log" 2>&1; rc=$?
set -e; status=$([[ $rc -eq 0 ]]&&echo pass||echo fail)
write_proof --out "$out" --scenario backup-restore --status "$status" --started-at "$started" --assertion "row-counts-match:$status:selected durable row counts matched after restore" --evidence "log:$log" --evidence "pg_dump:$dump" --config "compose:$ROOT/docker-compose.yml"; echo "$out"
